insert into public.pagamentos(legacy_id,usuario_id,bolao_id,participacao_id,valor,status,forma_pagamento,data_pagamento,pagador,recebedor,chave_pix,identificador_pix,hash_comprovante,observacao,legacy_payload)
select s.legacy_id,u.id,s.bolao_id,p.id,s.valor,s.status,s.forma,s.data_pagamento,s.pagador,s.recebedor,s.chave_pix,s.identificador,nullif(s.file_id,''),'Importado da planilha PAGAMENTOS',s.payload from mig_pay s left join public.usuarios u on lower(u.email)=lower(s.email) left join public.participacoes p on p.usuario_id=u.id and p.bolao_id=s.bolao_id
on conflict(legacy_id) do update set usuario_id=excluded.usuario_id,bolao_id=excluded.bolao_id,participacao_id=excluded.participacao_id,valor=excluded.valor,status=excluded.status,forma_pagamento=excluded.forma_pagamento,data_pagamento=excluded.data_pagamento,pagador=excluded.pagador,recebedor=excluded.recebedor,chave_pix=excluded.chave_pix,identificador_pix=excluded.identificador_pix,hash_comprovante=excluded.hash_comprovante,legacy_payload=excluded.legacy_payload;
insert into public.comprovantes(pagamento_id,usuario_id,nome_arquivo,mime_type,hash_arquivo,status,legacy_drive_url,legacy_id,ocr_dados,legacy_payload)
select pg.id,u.id,s.nome_arquivo,s.mime_type,nullif(s.file_id,''),coalesce(nullif(s.status,''),'RECEBIDO'),s.url,coalesce(nullif(s.file_id,''),s.legacy_id),'{}'::jsonb,jsonb_build_object('fonte','PAGAMENTOS') from mig_pay s join public.pagamentos pg on pg.legacy_id=s.legacy_id left join public.usuarios u on lower(u.email)=lower(s.email) where coalesce(s.url,'')<>'' or coalesce(s.file_id,'')<>''
on conflict(hash_arquivo) where hash_arquivo is not null and hash_arquivo<>'' do update set pagamento_id=excluded.pagamento_id,usuario_id=excluded.usuario_id,nome_arquivo=excluded.nome_arquivo,mime_type=excluded.mime_type,status=excluded.status,legacy_drive_url=excluded.legacy_drive_url;
commit;
